package org.jsoup.select;

import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.Node;
import org.junit.jupiter.api.Test;

import java.util.ArrayList;
import java.util.List;

import static org.jsoup.select.SelectorTest.assertSelectedIds;
import static org.junit.jupiter.api.Assertions.*;

class HasProbeTest {
    static String ids(org.jsoup.select.Elements els) {
        List<String> out = new ArrayList<>();
        for (Element el : els) out.add(el.id());
        return out.toString();
    }

    @Test void probeMultiBranchDedupOrder() {
        // both branches hit same candidate; parent and child both hit; order stable
        String html = "<div id=A><div id=B><p>x</p><span>y</span></div></div>";
        Document doc = Jsoup.parse(html);
        // branch1 p, branch2 span -> A and B both contain p and span; each once
        System.out.println("[div:has(p,span)] = " + ids(doc.select("div:has(p, span)")));
        // two branches both p
        System.out.println("[div:has(p,p)] = " + ids(doc.select("div:has(p, p)")));
        // one branch no match
        System.out.println("[div:has(p,zzz)] = " + ids(doc.select("div:has(p, zzz)")));
        System.out.println("[div:has(zzz,aaa)] size = " + doc.select("div:has(zzz, aaa)").size());
    }

    @Test void probeScopeNarrowing() {
        // descendant cannot escape candidate; child; siblings; nested
        String html = "<div id=A><p id=p1><b>b1</b></p><article id=art><h1>h</h1><h2>h2</h2></article></div>";
        Document doc = Jsoup.parse(html);
        System.out.println("[p:has(b)] = " + ids(doc.select("p:has(b)")));
        System.out.println("[p:has(> b)] = " + ids(doc.select("p:has(> b)")));
        System.out.println("[div:has(> p > b)] = " + ids(doc.select("div:has(> p > b)")));
        // h1~h2 inside art subtree
        System.out.println("[article:has(h1 ~ h2)] = " + ids(doc.select("article:has(h1 ~ h2)")));
        // h1+h2 inside
        System.out.println("[article:has(h1 + h2)] = " + ids(doc.select("article:has(h1 + h2)")));
        // descendant combinator must not see self: A element matching 'div' inside :has(div)?
        System.out.println("[div:has(div)] = " + ids(doc.select("div:has(div)"))); // expect A only
        // nested:has self leak
        System.out.println("[div:has(:has(b))] = " + ids(doc.select("div:has(:has(b))")));
    }

    @Test void probeErrors() {
        String[] bad = {
            "div:has()", "div:has(,)", "div:has(p,)", "div:has(,p)",
            "div:has(p", "div:has((p)", "div:has(p])", "div:has(+)",
            "div:has(>)", "div:has(~)", "div:has(p +)", "div:has(p,,q)",
            "div:has(p, (q))", ":has(p) :has(q"
        };
        for (String q : bad) {
            try {
                Jsoup.parse("<div id=A><p>x</p></div>").select(q);
                System.out.println("NO THROW for: " + q);
            } catch (Selector.SelectorParseException e) {
                System.out.println("throws OK: " + q + " :: " + e.getMessage());
            }
        }
    }

    @Test void probeStateAndRoundTrip() {
        String html = "<div id=A class=\"x y\"><p id=p>Hi &amp; co<span class='c\\l'>s</span></p></div>";
        Document doc1 = Jsoup.parse(html);
        String r1a = ids(doc1.select("div:has(p, span)"));
        String r1b = ids(doc1.select("div:has(p, span)"));
        assertEquals(r1a, r1b, "repeat query stable");

        Document doc2 = Jsoup.parse(html);
        String r2 = ids(doc2.select("div:has(p, span)"));
        assertEquals(r1a, r2, "cross-doc stable");

        // reused evaluator across docs
        Evaluator eval = QueryParser.parse("div:has(p, span)");
        assertEquals(ids(Selector.select(eval, doc1)), ids(Selector.select(eval, doc2)), "reused eval cross doc");
        assertEquals(ids(Selector.select(eval, doc2)), ids(Selector.select(eval, doc1)), "order of docs no leak");

        // serialization round trip
        String out1 = doc1.html();
        Document doc3 = Jsoup.parse(out1);
        assertEquals(ids(doc3.select("div:has(p, span)")), r1a, "roundtrip ids");
        assertEquals(out1, doc3.html(), "serialization unchanged by queries");

        // escaped class, quoted attr, entities
        Document d4 = Jsoup.parse("<div id=D><a class=\"foo bar\" title='He said &quot;hi&quot;' href=\"x?a=1&amp;b=2\">l</a></div>");
        System.out.println("escaped class: " + ids(d4.select("div:has(.foo\\.bar)"))); // none: class is foo, bar
        System.out.println("class foo: " + ids(d4.select("div:has(.foo)")));
        System.out.println("attr quoted entity: " + ids(d4.select("div:has(a[title='He said \"hi\"'])")));
        System.out.println("attr entity href: " + ids(d4.select("div:has(a[href='x?a=1&b=2'])")));
        System.out.println("wildcard: " + ids(d4.select("div:has(*))" )));
        System.out.println("not: " + ids(d4.select("div:has(a:not(.zzz))")));
    }

    @Test void probeAfterErrorDocUsable() {
        Document doc = Jsoup.parse("<div id=A><p id=p>x</p><b id=b>y</b></div>");
        try { doc.select("div:has(p, "); fail(); } catch (Selector.SelectorParseException expected) {}
        // doc still works
        assertSelectedIds(doc.select("p"), "p");
        assertSelectedIds(doc.select("[id]"), "A", "p", "b");
        assertSelectedIds(doc.select("div:has(p)"), "A");
        assertSelectedIds(doc.select("div:has(b, p)"), "A");
    }

    @Test void probeEmptyAndNoMatch() {
        Document empty = Jsoup.parse("");
        assertEquals(0, empty.select("div:has(p)").size());
        Document doc = Jsoup.parse("<div id=A></div>");
        assertEquals(0, doc.select("div:has(p)").size());
        assertEquals(0, doc.select("div:has(*)").size()); // empty div has no descendants
        System.out.println("empty doc select ok");
    }

    @Test void probeNestedPaths() {
        // candidate satisfies multiple nested paths simultaneously; dedupe
        String html = "<div id=A><section id=S><p><b>x</b></p><ul><li><b>y</b></li></ul></section></div>";
        System.out.println("nested multi: " + ids(doc0(html).select("div:has(section:has(p b, ul b))")));
        System.out.println("nested has-has: " + ids(doc0(html).select("div:has(p:has(b))")));
        // commas inside nested
        System.out.println("nested comma order: " + ids(doc0(html).select("div:has(:is(p, ul) b)")));
    }

    static Document doc0(String html) { return Jsoup.parse(html); }

    @Test void probeSiblingsEscape() {
        // :has(h1 ~ h2) must not escape subtree; construct h2 outside candidate but after it
        String html = "<div id=wrap><article id=art><h1>h</h1></article><h2>outside</h2></div>";
        Document doc = Jsoup.parse(html);
        System.out.println("art has h1~h2 (h2 outside) = " + ids(doc.select("article:has(h1 ~ h2)"))); // expect none
        System.out.println("art has ~ h2 (following sib) = " + ids(doc.select("article:has(~ h2)"))); // expect art
    }

    @Test void probeTablesListsForms() {
        String html = "<table id=t><tr id=tr><td id=td>1</td><td>2</td></tr></table>";
        Document doc = Jsoup.parse(html);
        System.out.println("table:has(tbody tr td): " + ids(doc.select("table:has(tr td)")));
        System.out.println("tr:has(> td + td): " + ids(doc.select("tr:has(> td + td)")));
        // unclosed tags
        Document d2 = Jsoup.parse("<div id=A><p>one<p>two<span>s</span></div>");
        System.out.println("unclosed p:has(span): " + ids(d2.select("div:has(p span)")));
        // nested forms (parser ignores inner form)
        Document d3 = Jsoup.parse("<form id=f1><input id=i1><form id=f2><input id=i2></form></form>");
        System.out.println("form:has(input): " + ids(d3.select("form:has(input)")));
    }

    @Test void probeNoMutation() {
        String html = "<div id=A><p id=p>x</p><!-- c --></div>";
        Document doc = Jsoup.parse(html);
        String before = doc.html();
        for (int i = 0; i < 100; i++) {
            doc.select("div:has(p, ::comment, + span)");
            doc.select("div:has(:scope ~ ::comment)");
        }
        assertEquals(before, doc.html(), "no mutation");
        // node identity unchanged
        Element p = doc.getElementById("p");
        assertNotNull(p);
    }

    @Test void probeWhitespaceEntitiesText() {
        Document doc = Jsoup.parse("<div id=A><p>  Hello   World  </p></div>");
        System.out.println("contains normalized: " + ids(doc.select("div:has(p:contains(Hello World))")));
    }
}

