package org.jsoup.select;

import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.junit.jupiter.api.Test;

import java.util.stream.IntStream;

import static org.jsoup.select.SelectorTest.assertSelectedIds;
import static org.junit.jupiter.api.Assertions.*;

class HasEdgeProbeTest {
    @Test void leadingPlusStaysElementAdjacentWhenLeafIsLater() {
        // text between the subject and its next element sibling must not block the leading + step,
        // even though a leaf is matched later inside that sibling
        Document doc = Jsoup.parse("<div id=a></div>text<!--between--><div><!--inside--></div>");
        assertSelectedIds(doc.select("#a:has(+ div ::comment)"), "a");
        assertSelectedIds(doc.select("#a:has(+ div > ::comment)"), "a");
        // element sibling itself, leaves ignored
        assertSelectedIds(doc.select("#a:has(+ div)"), "a");
        // but an immediate-node comment after an element gap is not adjacent
        Document doc2 = Jsoup.parse("<div id=a></div><p></p><!--c-->");
        assertEquals(0, doc2.select("#a:has(+ ::comment)").size());
        Document doc3 = Jsoup.parse("<div id=a></div><!--c-->");
        assertSelectedIds(doc3.select("#a:has(+ ::comment)"), "a");
    }

    @Test void internalLeafStepIsNodeAdjacent() {
        Document doc = Jsoup.parse("<article id=a></article><!--c--><b></b>txt<i></i>");
        assertSelectedIds(doc.select("article:has(+ ::comment + b)"), "a");
        assertEquals(0, doc.select("article:has(+ ::comment + b + i)").size()); // txt blocks
        Document doc2 = Jsoup.parse("<article id=a></article><!--x--><b></b>txt<i></i>");
        assertSelectedIds(doc2.select("article:has(+ b + i)"), "a"); // pure element chain
    }

    @Test void leafInsideSubtreeTightensOnlyThatStep() {
        Document doc = Jsoup.parse("<article id=a><h1></h1>txt<!--c--></article>");
        assertEquals(0, doc.select("article:has(h1 + ::comment)").size());
        assertSelectedIds(doc.select("article:has(h1 ~ ::comment)"), "a");
        Document doc2 = Jsoup.parse("<article id=a><h1></h1><!--c--></article>");
        assertSelectedIds(doc2.select("article:has(h1 + ::comment)"), "a");
    }

    @Test void nestedHasLeafDoesNotLeak() {
        // the ::comment inside the nested :has() must not switch the outer leading "+ div" to node adjacency
        Document doc = Jsoup.parse("<div id=a></div>txt<div><!--inside--></div>");
        assertSelectedIds(doc.select("#a:has(+ div:has(::comment))"), "a");
        assertSelectedIds(doc.select("#a:has(+ div:has(> ::comment))"), "a");
        // nested has leaf chain works on its own scope
        Document doc2 = Jsoup.parse("<article id=a><div><h1></h1>txt<!--c--></div></article>");
        assertEquals(0, doc2.select("article:has(div:has(h1 + ::comment))").size());
        Document doc3 = Jsoup.parse("<article id=a><div><h1></h1><!--c--></div></article>");
        assertSelectedIds(doc3.select("article:has(div:has(h1 + ::comment))"), "a");
    }

    @Test void compiledEvalConcurrentAndCrossDoc() {
        String query = "div:has(+ div ::comment, > a, p span)";
        Evaluator eval = Selector.evaluatorOf(query);
        IntStream.range(0, 16).parallel().forEach(i -> {
            Document doc = Jsoup.parse(
                "<div id=a></div>txt<div><!--c--></div><div id=b><a></a></div><div id=c><p><span></span></p></div>");
            assertEquals(doc.select(query), doc.select(eval));
            assertSelectedIds(doc.select(eval), "a", "b", "c");
